import{c as A,Q as i,j as t,m as s}from"./chunks/framework.DOi4mjdC.js";const e="/assets/%E9%80%9A%E4%BF%A1%E8%AE%A1%E7%AE%97%E8%9E%8D%E5%90%88%E5%89%8D%E5%90%8E%E7%9A%84%E7%90%86%E8%AE%BA%E6%89%A7%E8%A1%8C%E8%80%97%E6%97%B6%E5%AF%B9%E6%AF%94%E7%A4%BA%E6%84%8F%E5%9B%BE.DT2Gx1T2.png",a="/assets/%E5%BC%B1%E4%BE%9D%E8%B5%96%E8%AE%A1%E7%AE%97%E9%80%9A%E4%BF%A1%E4%BB%BB%E5%8A%A1%E7%A4%BA%E6%84%8F%E5%9B%BE.Crx6CSza.png",o="/assets/%E5%BC%B1%E4%BE%9D%E8%B5%96%E8%AE%A1%E7%AE%97%E9%80%9A%E4%BF%A1%E4%BB%BB%E5%8A%A1%E7%9A%84%E8%B0%83%E5%BA%A6%E6%A8%A1%E6%8B%9F%E7%A4%BA%E6%84%8F%E5%9B%BE.SpHhtAtA.png",R="data:image/png;base64,",B="/assets/%E5%BC%BA%E4%BE%9D%E8%B5%96%E8%AE%A1%E7%AE%97%E9%80%9A%E4%BF%A1%E4%BB%BB%E5%8A%A1%E7%9A%84%E8%B0%83%E5%BA%A6%E6%A8%A1%E6%8B%9F%E7%A4%BA%E6%84%8F%E5%9B%BE.CEMvGWhA.png",m=JSON.parse('{"title":"基础知识","description":"","frontmatter":{},"headers":[{"level":1,"title":"基础知识","slug":"基础知识"},{"level":2,"title":"通算融合算子","slug":"通算融合算子"},{"level":2,"title":"使用场景和优势","slug":"使用场景和优势"}],"relativePath":"guide/算子实践参考/SIMD算子实现/融合算子编程/通算融合/基础知识.md","filePath":"guide/算子实践参考/SIMD算子实现/融合算子编程/通算融合/基础知识.md"}'),r={name:"guide/算子实践参考/SIMD算子实现/融合算子编程/通算融合/基础知识.md"};function l(I,E,n,p,g,c){return i(),t("div",null,[...E[0]||(E[0]=[s('<h1 id="基础知识" tabindex="-1">基础知识 <a class="header-anchor" href="#基础知识" aria-label="Permalink to &quot;基础知识&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>本节内容为通算融合算子的理论背景和开发指导，学习本节内容之前，请确保已经掌握<a href="./../../矩阵编程（高阶API）/基础知识.html">矩阵编程</a>和<a href="https://www.hiascend.com/document/redirect/CannCommunityHcclUg" target="_blank" rel="noreferrer">《HCCL集合通信库》</a>中的相关知识。 通算融合算子一般支持如下产品型号：</p><blockquote><ul><li>Ascend 950PR/Ascend 950DT</li><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></blockquote></div><h2 id="通算融合算子" tabindex="-1">通算融合算子 <a class="header-anchor" href="#通算融合算子" aria-label="Permalink to &quot;通算融合算子&quot;">​</a></h2><p>相比于一般的计算或搬运类算子，通算融合算子将原本串行的通信和计算操作融合在一起，通过在算子内部进行数据切分，实现了计算和通信任务在算子内的并行执行，从而提升算子性能。通算融合算子统称为MC²算子，即Matrix Computation &amp; Communication。</p><p>如下图所示，串行的通信算子和计算算子的理想执行耗时为两个算子执行时间的加和，而在融合通信和计算任务得到的通算融合算子内，将需要通信和计算的数据进行切分，一次通信和计算的数据量减少，整个通信和计算任务分多次进行，使得计算与通信流水并行，理论执行耗时大大缩短，从而带来性能收益。</p><p><strong>图 1</strong> 通信计算融合前后的理论执行耗时对比示意图<br><img src="'+e+'" alt="" title="通信计算融合前后的理论执行耗时对比示意图"></p><h2 id="使用场景和优势" tabindex="-1">使用场景和优势 <a class="header-anchor" href="#使用场景和优势" aria-label="Permalink to &quot;使用场景和优势&quot;">​</a></h2><p>随着模型规模的增长，单设备上的训练和推理在计算能力、内存容量和能效等方面面临瓶颈，因此分布式并行计算成为必选技术路径。对于大模型分布式训练和推理过程中的通信和计算任务，可根据通信和计算的依赖关系分为两类：</p><ul><li><p>弱依赖计算通信任务</p><p>通信或计算的结果不会立即被对方使用，两者虽有依赖，但在两者中间可以调度执行其他无依赖的计算或通信任务。如<a href="#zh-cn_topic_0000002366728672_fig1840354818120">图2</a>所示，通信1与计算1-2、计算4有依赖关系，通信1与计算1-1、计算2-1、计算2-2、计算3无依赖关系；通信2与计算2-2、计算4有依赖关系，通信2与计算2-1、计算3无依赖关系。因此，通信1和通信2都有较大的流水空间，可以被与它们无依赖的计算任务所掩盖。如<a href="#zh-cn_topic_0000002366728672_fig382061611816">图3</a>所示，通信1和通信2均可以被无依赖的计算任务掩盖。在模型中，此类无依赖的通信和计算可以实现任务级并行，无需做算子融合。因此，弱依赖计算通信任务不适用通算融合场景。</p><p><strong>图 2</strong> 弱依赖计算通信任务示意图<br><img src="'+a+'" alt="" title="弱依赖计算通信任务示意图"></p><p><strong>图 3</strong> 弱依赖计算通信任务的调度模拟示意图<br><img src="'+o+'" alt="" title="弱依赖计算通信任务的调度模拟示意图"></p></li><li><p>强依赖计算通信任务</p><p>通信或计算的结果立即被对方使用，两者间存在紧密依赖关系。如下图所示，计算通信任务必须串行执行，在通信1和通信2执行过程中，硬件计算资源闲置，此类通信计算模式若在模型中大量出现，将导致算力利用率低，通信成为主要性能瓶颈。强依赖计算通信任务适合融合为通算融合算子，利用通算融合技术提升性能。</p><p><strong>图 4</strong> 强依赖计算通信任务示意图<br><img src="'+R+'" alt="" title="强依赖计算通信任务示意图"></p><p><strong>图 5</strong> 强依赖计算通信任务的调度模拟示意图<br><img src="'+B+'" alt="" title="强依赖计算通信任务的调度模拟示意图"></p></li></ul><p>通算融合技术与网络模型结构密切相关，一般而言，符合上述强依赖计算通信任务都有可能通过通算融合算子实现性能提升。</p>',10)])])}const h=A(r,[["render",l]]);export{m as __pageData,h as default};
